"""One-page weekly summary for printing: food cost, waste by day and station."""
from dataclasses import dataclass, field

STATIONS = ["grill", "fry", "cold", "bar", "other"]

@dataclass
class WasteEntry:
    day: str       # "Mon".."Sun"
    station: str   # one of STATIONS
    cost: float    # dollars wasted

@dataclass
class WeekSummary:
    revenue: float
    food_purchases: float
    waste: list = field(default_factory=list)

    def waste_total(self) -> float:
        return sum(e.cost for e in self.waste)

    def waste_by(self, key) -> dict:
        out = {}
        for e in self.waste:
            k = getattr(e, key)
            out[k] = out.get(k, 0.0) + e.cost
        return out

    def render(self) -> str:
        fc = 100 * self.food_purchases / self.revenue if self.revenue else 0.0
        wp = 100 * self.waste_total() / self.revenue if self.revenue else 0.0
        lines = [
            "WEEKLY FOOD COST SUMMARY",
            f"Revenue: ${self.revenue:,.2f}",
            f"Food purchases: ${self.food_purchases:,.2f}  (food cost {fc:.1f}%)",
            f"Logged waste: ${self.waste_total():,.2f}  ({wp:.1f}% of revenue)",
            "Waste by day:",
        ]
        for d in ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]:
            v = self.waste_by("day").get(d, 0.0)
            if v:
                lines.append(f"  {d}: ${v:,.2f}")
        lines.append("Waste by station:")
        for s, v in sorted(self.waste_by("station").items(), key=lambda x: -x[1]):
            lines.append(f"  {s}: ${v:,.2f}")
        return "\n".join(lines)

if __name__ == "__main__":
    w = WeekSummary(revenue=18000, food_purchases=5400,
                    waste=[WasteEntry("Fri", "fry", 120.0), WasteEntry("Sat", "cold", 80.5)])
    print(w.render())
EOF
